function ipToInt(ip) {
  const parts = String(ip).trim().split(".").map(Number);
  if (parts.length !== 4 || parts.some(n => Number.isNaN(n) || n < 0 || n > 255)) return null;
  return (((parts[0] << 24) >>> 0) + (parts[1] << 16) + (parts[2] << 8) + parts[3]) >>> 0;
}

function isIpInRange(ip, range) {
  const [start, endRaw] = String(range).split("-").map(s => s.trim());
  if (!start || !endRaw) return false;

  let end = endRaw;

  // รองรับ 192.168.87.130-139
  if (!end.includes(".")) {
    const p = start.split(".");
    if (p.length === 4) {
      end = `${p[0]}.${p[1]}.${p[2]}.${end}`;
    }
  }

  const n = ipToInt(ip);
  const a = ipToInt(start);
  const b = ipToInt(end);

  if (n === null || a === null || b === null) return false;
  return n >= Math.min(a, b) && n <= Math.max(a, b);
}

function isIpInCidr(ip, cidr) {
  const [base, maskText] = String(cidr).split("/");
  const mask = Number(maskText);
  const n = ipToInt(ip);
  const b = ipToInt(base);

  if (n === null || b === null || Number.isNaN(mask) || mask < 0 || mask > 32) return false;

  const m = mask === 0 ? 0 : (0xffffffff << (32 - mask)) >>> 0;
  return (n & m) === (b & m);
}

function pickHost(v) {
  return (
    v.host_ip ||
    v.hostIp ||
    v.ip ||
    v.target ||
    v.host ||
    v.hostname ||
    v.asset_ip ||
