  return (
    catalog.description ||
    catalog.summary ||
    catalog.security_demo?.description ||
    catalog.security_demo?.summary ||
    ""
  );
}

function getCatalogRemediation(catalog) {
  return (
    catalog.remediation ||
    catalog.fix ||
    catalog.recommendation ||
    catalog.security_demo?.remediation ||
    "Review endpoint exposure, authentication, authorization, and sensitive data handling."
  );
}

// ------------------------------
// 1) ดึง endpoint ที่ Metlo เคยเห็นจริง
// ------------------------------
const rawEndpoints = [];

for (const item of endpointItems) {
  rawEndpoints.push(...asArray(item));
  rawEndpoints.push(...asArray(item.data));
  rawEndpoints.push(...asArray(item.items));
  rawEndpoints.push(...asArray(item.results));
  rawEndpoints.push(...asArray(item.endpoints));

  if (looksLikeEndpoint(item)) {
    rawEndpoints.push(item);
  }

  if (looksLikeEndpoint(item["0"])) {
    rawEndpoints.push(item["0"]);
  }
}

// ------------------------------
// 2) ดึง alerts จาก summary เอาไว้เสริมข้อมูล
// ------------------------------
const alerts = [];

for (const item of summaryItems) {
  alerts.push(...asArray(item.topAlerts));
  alerts.push(...asArray(item.alerts));
  alerts.push(...asArray(item.data?.topAlerts));
  alerts.push(...asArray(item.data?.alerts));
}

const alertsByEndpoint = new Map();

for (const alert of alerts) {
  const ep = alert.apiEndpoint || alert.endpoint || alert;
  const key = endpointKey(getMethod(ep), getPath(ep), getHost(ep));

  if (!alertsByEndpoint.has(key)) {
    alertsByEndpoint.set(key, []);
  }

  alertsByEndpoint.get(key).push(alert);
}

// ------------------------------
// 3) กรอง endpoint ให้เหลือเฉพาะ target ที่ผู้ใช้กรอก
// ------------------------------
const uniqueEndpoints = [];
const seenObserved = new Set();

for (const endpoint of rawEndpoints) {
  const method = getMethod(endpoint);
  const path = getPath(endpoint);
  const host = getHost(endpoint);

  if (method === "UNKNOWN" && path === "Unknown Endpoint") continue;
  if (!isEndpointForTarget(endpoint)) continue;

  const key = endpoint.uuid || endpointKey(method, path, host);

  if (!seenObserved.has(key)) {
    seenObserved.add(key);
    uniqueEndpoints.push(endpoint);
  }
}

// ------------------------------
// 4) สร้าง map ของ observed endpoint
// ------------------------------
const observedByMethodPath = new Map();

for (const endpoint of uniqueEndpoints) {
  const method = getMethod(endpoint);
  const path = getPath(endpoint);

  observedByMethodPath.set(catalogKey(method, path), endpoint);
}

// ------------------------------
// 5) ดึง catalog endpoint ทั้งหมดจาก Get Security Catalog
// ------------------------------
let catalogEndpoints = [];

for (const item of catalogItems) {
  catalogEndpoints.push(...asArray(item.endpoints));
  catalogEndpoints.push(...asArray(item.routes));
  catalogEndpoints.push(...asArray(item.catalog));
  catalogEndpoints.push(...asArray(item.data));
  catalogEndpoints.push(...asArray(item.items));
  catalogEndpoints.push(...asArray(item.results));

  if (looksLikeEndpoint(item) && (item.severity || item.authRequired !== undefined || item.security_demo)) {
    catalogEndpoints.push(item);
  }
}

// กัน catalog ซ้ำ
const uniqueCatalogEndpoints = [];
const seenCatalog = new Set();

for (const catalog of catalogEndpoints) {
  const method = getCatalogMethod(catalog);
  const path = getCatalogPath(catalog);
  const key = catalogKey(method, path);

  if (!seenCatalog.has(key)) {
    seenCatalog.add(key);
    uniqueCatalogEndpoints.push(catalog);
  }
}

// ------------------------------
// 6) สร้าง findings
// ถ้ามี catalog → ใช้ catalog เป็นหลัก
// ถ้าไม่มี catalog → fallback ใช้ observed endpoints จาก Metlo
// ------------------------------
const findings = [];

if (uniqueCatalogEndpoints.length > 0) {
  for (const catalog of uniqueCatalogEndpoints) {
    const method = getCatalogMethod(catalog);
    const path = getCatalogPath(catalog);
    const normalizedKey = catalogKey(method, path);

    const observed = observedByMethodPath.get(normalizedKey);
    const hasAccess = !!observed;

    const host = observed ? getHost(observed) : targetHost;

    const firstSeen = observed
      ? pickFirst(
          observed.firstDetected,
          observed.createdAt,
          observed.updatedAt
        )
      : null;

    const lastSeen = observed
      ? pickFirst(
          observed.lastActive,
          observed.updatedAt,
          firstSeen
        )
      : null;

    const observedRange =
      firstSeen && lastSeen
        ? `${firstSeen} → ${lastSeen}`
        : (lastSeen || firstSeen || "");

    const severity = getCatalogSeverity(catalog);
    const authRequired = getCatalogAuthRequired(catalog);
    const risk = getCatalogRisk(catalog);
    const catalogDescription = getCatalogDescription(catalog);

    const descriptionParts = [
      hasAccess
        ? "This endpoint exists in the application security catalog and has been observed by Metlo from real application traffic."
        : "This endpoint exists in the application security catalog but has not been observed by Metlo traffic yet.",
      `Endpoint: ${method} ${path}.`,
      `Auth required: ${authRequired ? "yes" : "no"}.`
    ];

    if (risk) descriptionParts.push(`Risk: ${risk}.`);
    if (catalogDescription) descriptionParts.push(`Details: ${catalogDescription}.`);
    if (firstSeen) descriptionParts.push(`First detected: ${firstSeen}.`);
    if (lastSeen) descriptionParts.push(`Last active: ${lastSeen}.`);

    findings.push({
      title: hasAccess
        ? safeText(`API Traffic Observed - ${method} ${path}`, "Metlo API Endpoint", 200)
        : safeText(`API Endpoint Not Accessed Yet - ${method} ${path}`, "Metlo API Endpoint", 200),

      severity,
      description: safeText(descriptionParts.join(" "), "Metlo API endpoint record.", 1500),
      remediation: getCatalogRemediation(catalog),
      target: host || fallbackTarget,
      status: "OPEN",
      cvss: Number(catalog.cvss || catalog.security_demo?.cvss || 0),
      tool: "metlo",

      // ให้ frontend เอา Age จาก lastSeen / ageLabel
      // ถ้ายังไม่เคย access จะไม่ใส่ createdAt เป็นเวลาปัจจุบัน เพราะจะทำให้ขึ้น just now
      createdAt: hasAccess ? (lastSeen || firstSeen) : null,
      firstSeen: firstSeen || null,
      lastSeen: lastSeen || null,
      observedRange,

      ageLabel: hasAccess ? null : "No access yet",
      accessStatus: hasAccess ? "accessed" : "no_access",
      metloObserved: hasAccess,

      authRequired,
      endpointPath: path,
      method
    });
  }
} else {
  // fallback กรณียังไม่มี Get Security Catalog หรือ catalog ว่าง
  for (const endpoint of uniqueEndpoints) {
    const method = getMethod(endpoint);
    const path = getPath(endpoint);
    const host = getHost(endpoint);

    const key = endpointKey(method, path, host);
    const matchedAlerts = alertsByEndpoint.get(key) || [];
    const firstAlert = matchedAlerts[0] || {};

    const risk = pickFirst(
      endpoint.riskScore,
      endpoint.risk,
      endpoint.riskLevel,
      endpoint.risk_level,
      endpoint.severity,
      endpoint.threatLevel,
      endpoint.threat_level,
      firstAlert.riskScore,
      firstAlert.risk,
      firstAlert.riskLevel,
      firstAlert.risk_level,
      firstAlert.severity,
      "none"
    );

    const severity = riskToSeverity(risk);

    const firstSeen = pickFirst(
      endpoint.firstDetected,
      endpoint.createdAt,
      firstAlert.createdAt,
      endpoint.updatedAt
    );

    const lastSeen = pickFirst(
      endpoint.lastActive,
      endpoint.updatedAt,
      firstAlert.createdAt,
      firstSeen
    );

    const observedRange =
      firstSeen && lastSeen
        ? `${firstSeen} → ${lastSeen}`
        : (lastSeen || firstSeen || "");

    findings.push({
      title: safeText(`API Traffic Observed - ${method} ${path}`, "Metlo API Endpoint", 200),
      severity,
      description: safeText(
        [
          "Metlo observed this API endpoint from application traffic.",
          host ? `Host: ${host}.` : "",
          `Endpoint: ${method} ${path}.`,
          risk ? `Risk score: ${risk}.` : "",
          firstSeen ? `First detected: ${firstSeen}.` : "",
          lastSeen ? `Last active: ${lastSeen}.` : ""
        ].filter(Boolean).join(" "),
        "Metlo observed an API endpoint.",
        1500
      ),
      remediation: "Review endpoint exposure, authentication, authorization, and sensitive data handling.",
      target: host || fallbackTarget,
      status: "OPEN",
      cvss: 0,
      tool: "metlo",

      createdAt: lastSeen || firstSeen || null,
      firstSeen: firstSeen || null,
      lastSeen: lastSeen || null,
      observedRange,

      ageLabel: null,
      accessStatus: "accessed",
      metloObserved: true,

      authRequired: endpoint.isAuthenticatedDetected === true,
      endpointPath: path,
      method
    });
  }
}

// ------------------------------
// 7) fallback ถ้าไม่มีอะไรเลย
// ------------------------------
if (findings.length === 0) {
  findings.push({
    title: "METLO Data Retrieved",
    severity: "INFO",
    description: "Metlo data was retrieved, but no observed API endpoints or security catalog entries were parsed.",
    remediation: "Check get metlo req1 output and Get Security Catalog output.",
