  if (t === "domain") {
    return (
      parameters.domain ||
      body.domain ||
      parameters.target ||
      body.target ||
      body.targets?.[0]
    );
  }

  return (
    parameters.target_ip ||
    parameters.target ||
    body.target_ip ||
    body.target ||
    body.targets?.[0]
  );
}

